#nullable enable // autogenerated

using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Modifiers;
using UnityEngine;

namespace MVZ2.GameContent.Projectiles
{
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.projectilePointToDirection)]
    public class ProjectilePointToDirectionBehaviour : EntityBehaviourDefinition
    {
        public ProjectilePointToDirectionBehaviour(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new Vector3Modifier(EngineEntityProps.BOUNDS_ROTATION, NumberOperator.Set, PROP_BOUNDS_ROTATION));
        }

        public override void Init(Entity entity)
        {
            base.Init(entity);
            UpdateDirection(entity);
        }

        public override void Update(Entity entity)
        {
            base.Update(entity);
            UpdateDirection(entity);
        }
        public static void UpdateDirection(Entity entity)
        {
            UpdateRenderRotation(entity);
            UpdateBoundsRotation(entity);
        }
        public static void UpdateRenderRotation(Entity entity)
        {
            var vel = new Vector2(entity.Velocity.x, entity.Velocity.y + entity.Velocity.z);
            entity.RenderRotation = Vector3.forward * Vector2.SignedAngle(Vector2.right, vel);
        }
        public static void UpdateBoundsRotation(Entity entity)
        {
            var rotation = Quaternion.FromToRotation(Vector3.right, entity.Velocity);
            var euler = rotation.eulerAngles;
            SetBoundsRotation(entity, euler);
        }
        private static void SetBoundsRotation(Entity entity, Vector3 value) => entity.SetProperty(PROP_BOUNDS_ROTATION, value);
        private static Vector3 GetBoundsRotation(Entity entity) => entity.GetProperty<Vector3>(PROP_BOUNDS_ROTATION);
        public static readonly VanillaEntityPropertyMeta<Vector3> PROP_BOUNDS_ROTATION = new VanillaEntityPropertyMeta<Vector3>("bounds_rotation");
    }
}